package com.edtech.platform.booking.repository; import com.edtech.platform.booking.domain.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import jakarta.persistence.LockModeType; import java.util.*; public interface TrialRequestRepository extends JpaRepository<TrialRequest,UUID>{ boolean existsByTeacherIdAndStudentIdAndStatus(UUID t,UUID s,TrialRequestStatus st); Page<TrialRequest> findByTeacherId(UUID t,Pageable p); Page<TrialRequest> findByStudentId(UUID studentId,Pageable p); Page<TrialRequest> findByStudentIdAndStatus(UUID studentId,TrialRequestStatus status,Pageable p); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select r from TrialRequest r where r.id=:id") Optional<TrialRequest> findByIdForUpdate(UUID id); }
